{
  "$schema": "https://json-schema.org/draft-07/schema#",
  "type": "object",
  "properties": {
    "receipt_id": {
      "type": "string",
      "description": "回执唯一标识符"
    },
    "timestamp": {
      "type": "string",
      "format": "date-time",
      "description": "UTC时间戳，精确到毫秒"
    },
    "observed": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string"
          },
          "source": {
            "type": "string",
            "description": "出处：必须为明确可追溯的原始证据标识（如日志路径、传感器ID、文档哈希等）"
          },
          "observation": {
            "type": "string",
            "description": "观察陈述：中性、可验证的事实描述，不含解释或归因"
          },
          "hypothesis": {
            "type": ["string", "null"],
            "description": "假设陈述：仅当存在明确提出的因果/机制推论时填写；否则为 null"
          },
          "action_taken": {
            "type": "string",
            "enum": ["none", "dispatched", "fixed", "escalated"],
            "description": "针对该观所采取的动作"
          },
          "follow_up_receipt": {
            "type": ["string", "null"],
            "description": "后续动作的回执ID（如派单号、工单号、升级跟踪码）；若 action_taken === 'none'，则必须为 null"
          },
          "status": {
            "type": "string",
            "enum": ["open", "closed"],
            "description": "仅当 action_taken !== 'none' 时可为 'closed'；若 action_taken === 'none'，此字段必须为 'open'"
          }
        },
        "required": ["id", "source", "observation", "action_taken", "follow_up_receipt", "status"],
        "additionalProperties": false
      }
    },
    "test_status": {
      "type": "object",
      "properties": {
        "model_proposed": {
          "type": "boolean",
          "description": "模型已提出待验证方案（未运行）"
        },
        "tested_by_model_claim": {
          "type": "boolean",
          "description": "模型声称已通过其内部仿真/推理完成验证（非实测）"
        },
        "actually_run": {
          "type": ["boolean", "null"],
          "description": "是否在真实环境或可信沙箱中实际执行过该方案"
        },
        "run_id": {
          "type": ["string", "null"],
          "description": "仅当 actually_run === true 时必需；实测运行唯一标识"
        },
        "sha256": {
          "type": ["string", "null"],
          "pattern": "^[a-fA-F\\d]{64}$",
          "description": "仅当 actually_run === true 时必需；对应 run_id 的完整执行包/镜像/脚本的 SHA-256 校验和"
        }
      },
      "required": ["model_proposed", "tested_by_model_claim", "actually_run"],
      "if": {
        "properties": {
          "actually_run": { "const": true }
        }
      },
      "then": {
        "required": ["run_id", "sha256"]
      },
      "else": {
        "properties": {
          "run_id": { "type": "null" },
          "sha256": { "type": "null" }
        }
      },
      "additionalProperties": false
    },
    "payment": {
      "type": ["object", "null"],
      "properties": {
        "paid": {
          "type": "boolean",
          "description": "是否已支付（仅布尔值，不包含金额、币种、时间等）"
        },
        "tx_hash": {
          "type": ["string", "null"],
          "description": "链上交易哈希（若 paid === true）；否则为 null"
        }
      },
      "required": ["paid", "tx_hash"],
      "additionalProperties": false
    }
  },
  "required": ["receipt_id", "timestamp", "observed", "test_status", "payment"],
  "additionalProperties": false
}
【交付结束】
